ST.xhtml:p:
F_PowerOff(CLK := g_bDriveEnable);
IF F_PowerOff.Q THEN
  General1_Enable := FALSE;
  General2_Enable := FALSE;
END_IF;


IF g_General1_Power.Error THEN
  General1_Enable := FALSE;
END_IF;
AxisPowerBrake(
	bPower := General1_Enable,
    AxisRef := REF(g_General1_Axis),
    HomeSignal :=g_nGeneralHomeSignal1,
    HomeMode := g_nT1HomeMode,
    AxisPosLimit := NOT g_bGeneral1PosLimit,
    AxisNegLimit := NOT g_bGeneral1NegLimit,
    AxisPower := REF(g_General1_Power),
    OutBrake => g_boGeneralAxis1HoldBrake);

IF g_General2_Power.Error THEN
  General2_Enable := FALSE;
END_IF;
AxisPowerBrake1(
	bPower := General2_Enable,
    AxisRef := REF(g_General2_Axis),
    HomeSignal :=g_nGeneralHomeSignal2,
    HomeMode := g_nT2HomeMode,
    AxisPosLimit := NOT g_bGeneral2PosLimit,
    AxisNegLimit := NOT g_bGeneral2NegLimit,
    AxisPower := REF(g_General2_Power),
    OutBrake => g_boGeneralAxis2HoldBrake);

g_General1_Override.ENABLE := TRUE;
g_General2_Override.ENABLE := TRUE;

IF NOT g_bG1_AxisInABS THEN
  g_General1_Override.VELFACTOR := g_dCurOverride;
END_IF;
IF NOT g_bG2_AxisInABS THEN
  g_General2_Override.VELFACTOR := g_dCurOverride;
END_IF;
IF ABS(g_General1_Axis.NCTOPLC.ACTPOS - g_General1_Axis.NCTOPLC.SETPOS) > g_fT1AxisMaxPosError THEN
  g_bT1AxisPosErrorAlarm := TRUE;
ELSE
  g_bT1AxisPosErrorAlarm := FALSE;
END_IF;
IF ABS(g_General2_Axis.NCTOPLC.ACTPOS - g_General2_Axis.NCTOPLC.SETPOS) > g_fT2AxisMaxPosError THEN
  g_bT2AxisPosErrorAlarm := TRUE;
ELSE
  g_bT2AxisPosErrorAlarm := FALSE;
END_IF;
